#import <Foundation/Foundation.h>
#import <AVFoundation/AVFoundation.h>
#import <AppKit/AppKit.h>
int main(int argc, const char * argv[]) { @autoreleasepool {
 NSString *video=[NSString stringWithUTF8String:argv[1]];
 NSString *out=[NSString stringWithUTF8String:argv[2]];
 AVURLAsset *asset=[AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:video] options:nil];
 double duration=CMTimeGetSeconds(asset.duration);
 printf(\"DURATION_SECONDS %.2f\\n\",duration);
 AVAssetImageGenerator *gen=[[AVAssetImageGenerator alloc] initWithAsset:asset];
 gen.appliesPreferredTrackTransform=YES;
 gen.maximumSize=CGSizeMake(1000,1000);
 for(int i=0;i<8;i++) {
  double sec=fmax(0.3,duration*i/8.0); NSError *error=nil;
  CGImageRef cg=[gen copyCGImageAtTime:CMTimeMakeWithSeconds(sec,600) actualTime:NULL error:&error];
  if(cg) { NSBitmapImageRep *rep=[[NSBitmapImageRep alloc] initWithCGImage:cg];
   NSData *data=[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
   NSString *file=[out stringByAppendingPathComponent:[NSString stringWithFormat:@\"frame-%02d.png\",i]];
   [data writeToFile:file atomically:YES]; printf(\"%s %.2f\\n\",file.UTF8String,sec); CGImageRelease(cg);
  } else { NSLog(@\"%@\",error); }
 }
 } return 0; }
